cat > /tmp/bot-check.mjs <<'EOF'
import assert from "node:assert/strict";
import { decideWhatsApp as d } from "<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round6-dev1-haiku/work/ours-g5-2/bot.mjs";

const T0 = "1767272400";                    // 2026-01-01T13:00:00Z (seconds)
const t0 = Number(T0) * 1000;
const at = (ms) => new Date(t0 + ms);
const H = 3600e3;
const c = (over = {}) => ({ optedIn: true, lastInboundTimestamp: T0, ...over });
const text = (contact) => ({ type: "text", contact });
const tpl = (contact) => ({ type: "template", contact });
const ok = { allowed: true, reason: null };
const no = (reason) => ({ allowed: false, reason });

// templates
assert.deepEqual(d(tpl(c()), at(0)), ok);
assert.deepEqual(d(tpl(c()), at(1000 * H)), ok);
assert.deepEqual(d(tpl(c({ lastInboundTimestamp: null })), at(0)), ok);
// text inside window
assert.deepEqual(d(text(c()), at(0)), ok);
assert.deepEqual(d(text(c()), at(23 * H + 59 * 60e3 + 59e3)), ok);
// text at/after 24h
assert.deepEqual(d(text(c()), at(24 * H)), no("service_window_expired"));
assert.deepEqual(d(text(c()), at(30 * H)), no("service_window_expired"));
// text never written to us
assert.deepEqual(d(text(c({ lastInboundTimestamp: null })), at(0)), no("no_inbound_message_service_window_closed"));
// opt-in beats everything
assert.deepEqual(d(tpl(c({ optedIn: false })), at(0)), no("contact_not_opted_in"));
assert.deepEqual(d(text(c({ optedIn: false })), at(0)), no("contact_not_opted_in"));
assert.deepEqual(d(text(c({ optedIn: "true" })), at(0)), no("contact_not_opted_in"));
// unknown type
assert.deepEqual(d({ type: "image", contact: c() }, at(0)), no("unknown_message_type"));
// bad timestamps
assert.deepEqual(d(text(c({ lastInboundTimestamp: T0 + "000" })), at(0)), no("invalid_inbound_timestamp")); // ms
assert.deepEqual(d(text(c({ lastInboundTimestamp: 1767272400 })), at(0)), no("invalid_inbound_timestamp")); // number
assert.deepEqual(d(text(c({ lastInboundTimestamp: "abc" })), at(0)), no("invalid_inbound_timestamp"));
assert.deepEqual(d(text(c({ lastInboundTimestamp: "" })), at(0)), no("invalid_inbound_timestamp"));
assert.deepEqual(d(text(c({ lastInboundTimestamp: "-5" })), at(0)), no("invalid_inbound_timestamp"));
assert.deepEqual(d(text(c({ lastInboundTimestamp: "1767272400.5" })), at(0)), no("invalid_inbound_timestamp"));
assert.deepEqual(d(text(c({ lastInboundTimestamp: T0 })), new Date(t0 - 10 * 60e3)), no("invalid_inbound_timestamp")); // 10 min in future
assert.deepEqual(d(text(c()), new Date(t0 - 60e3)), ok); // 1 min skew tolerated
// bad now
assert.throws(() => d(text(c()), new Date("x")), TypeError);
assert.throws(() => d(text(c()), Date.now()), TypeError);
// reasons are distinct per rule
const reasons = ["contact_not_opted_in", "unknown_message_type", "no_inbound_message_service_window_closed", "invalid_inbound_timestamp", "service_window_expired"];
assert.equal(new Set(reasons).size, reasons.length);
console.log("all checks passed");
EOF
node /tmp/bot-check.mjs && node -e 'import("./bot.mjs").then(m=>console.log(Object.keys(m)))' && rm /tmp/bot-check.mjs
